$lines = [];
while ($line = fgets(STDIN)) {
    $lines[] = rtrim($line);
}
$iroha_order = array_flip(mb_str_split("いろはにほへとちりぬるを"));
usort($lines, function ($a, $b) use ($iroha_order) {
    $len = min(mb_strlen($a), mb_strlen($b));
    for ($i = 0; $i < $len; $i++) {
        $ca = mb_substr($a, $i, 1);
        $cb = mb_substr($b, $i, 1);
        if ($ca !== $cb) {
            return $iroha_order[$ca] - $iroha_order[$cb];
        }
    }
    return mb_strlen($a) - mb_strlen($b);
});

foreach ($lines as $line) echo $line, PHP_EOL;
